function craftCoreEssence(){
 const p=state.player;if(p.realmIndex<12)return showResult('境界不足','至少达到筑基后期，才能承受淬炼结丹灵髓时的灵压。','bad');if(!CORE_REFINING_LOCATIONS.includes(p.location))return showResult('地脉不合','淬炼结丹灵髓需要前往赤霞谷、落星矿脉或古河遗迹，借当地灵脉成髓。','bad');if(p.herbs<4||p.beastMaterials<2||p.spiritStones<6)return showResult('材料不足','每份结丹灵髓需要：灵草 4、兽材 2、灵石 6。\n当前：灵草 '+p.herbs+'、兽材 '+p.beastMaterials+'、灵石 '+p.spiritStones+'。','bad');
 p.herbs-=4;p.beastMaterials-=2;p.spiritStones-=6;advanceDays(2);if(state.flags.dead)return;p.coreEssence=(p.coreEssence||0)+1;addDiligence(3);addPersonal('你借'+p.location+'地脉淬炼出一份【结丹灵髓】。','major');save();render();showResult('结丹灵髓炼成','结丹灵髓 +1\n灵草 -4\n兽材 -2\n灵石 -6\n耗时 2 日','good')
}
function craftNascentEssence(){
 const p=state.player;if(p.realmIndex<17)return showResult('境界不足','至少达到金丹后期，才有资格淬炼化婴灵胎。','bad');if(!NASCENT_REFINING_LOCATIONS.includes(p.location))return showResult('地脉不合','化婴灵胎只能借古河遗迹残禁或玄阴禁地阴阳逆转之力淬炼。','bad');if((p.coreEssence||0)<1||(p.relicFragments||0)<2||p.herbs<6||p.spiritStones<12)return showResult('材料不足','每份化婴灵胎需要：结丹灵髓1、古修残片2、灵草6、灵石12。','bad');
 p.coreEssence--;p.relicFragments-=2;p.herbs-=6;p.spiritStones-=12;advanceDays(3);if(state.flags.dead)return;p.nascentEssence=(p.nascentEssence||0)+1;addDiligence(4);addPersonal('你在'+p.location+'压住丹火与阴阳灵机，炼成一份【化婴灵胎】。','major');save();render();showResult('化婴灵胎炼成','化婴灵胎 +1\n结丹灵髓 -1\n古修残片 -2\n灵草 -6\n灵石 -12\n耗时 3 日','good')
}
function craftDeificationEssence(){
 const p=state.player;if(p.realmIndex<21)return showResult('境界不足','至少达到元婴后期，神识足够强大后才能淬炼化神道种。','bad');if(!DEIFICATION_REFINING_LOCATIONS.includes(p.location))return showResult('地脉不合','化神道种只能借古河遗迹的残存神禁或玄阴禁地的阴神之力淬炼。','bad');if((p.nascentEssence||0)<1||(p.relicFragments||0)<3||p.beastMaterials<4||p.herbs<8||p.spiritStones<25)return showResult('材料不足','每份化神道种需要：化婴灵胎1、古修残片3、兽材4、灵草8、灵石25。','bad');
 p.nascentEssence--;p.relicFragments-=3;p.beastMaterials-=4;p.herbs-=8;p.spiritStones-=25;advanceDays(4);if(state.flags.dead)return;p.deificationEssence=(p.deificationEssence||0)+1;addDiligence(5);addPersonal('你在'+p.location+'以元婴神识反复祭炼，凝成一枚【化神道种】。','major');save();render();showResult('化神道种凝成','化神道种 +1\n化婴灵胎 -1\n古修残片 -3\n兽材 -4\n灵草 -8\n灵石 -25\n耗时 4 日','good')
}
function claimGoldenCoreInheritance(){
 const p=state.player;if(p.realmIndex<15)return showResult('境界不足','凝成金丹后，才有资格承受这套高阶传承。','bad');if(p.spells&&('金焰剑诀'in p.spells))return showResult('已经掌握','你已经掌握《丹霞金章》、金焰剑诀与护体灵罡。');if(!['青云山','古河遗迹'].includes(p.location))return showResult('传承不在此地','需前往青云山宗门藏经地或古河遗迹残碑处参悟。','bad');if(p.spiritStones<40||p.insight<3||p.relicFragments<2)return showResult('准备不足','参悟高阶传承需要：灵石40、悟道点3、古修残片2。','bad');p.spiritStones-=40;p.insight-=3;p.relicFragments-=2;p.manual='丹霞金章';p.manualProf=0;p.spells['金焰剑诀']=0;p.spells['护体灵罡']=0;addPersonal('你完成高阶传承参悟，改修《丹霞金章》，并掌握金焰剑诀、护体灵罡。','major');save();render();showResult('高阶传承入手','改修《丹霞金章》\n掌握【金焰剑诀】\n掌握【护体灵罡】','good')
}
function claimSpiritTransformationInheritance(){
 const p=state.player;if(p.realmIndex<23)return showResult('境界不足','真正踏入化神后，才能承受神识化域的传承。','bad');if(p.spells&&('神念斩'in p.spells))return showResult('已经掌握','你已经掌握《太虚化神篇》、神念斩与元神法域。');if(!['古河遗迹','玄阴禁地'].includes(p.location))return showResult('传承不在此地','需前往古河遗迹或玄阴禁地，以神识触碰残存化神道痕。','bad');if(p.spiritStones<120||p.insight<5||p.relicFragments<5)return showResult('准备不足','参悟化神传承需要：灵石120、悟道点5、古修残片5。','bad');p.spiritStones-=120;p.insight-=5;p.relicFragments-=5;p.manual='太虚化神篇';p.manualProf=0;p.spells['神念斩']=0;p.spells['元神法域']=0;addPersonal('你以元神触及化神道痕，改修《太虚化神篇》，并掌握神念斩与元神法域。','major');save();render();showResult('化神传承入手','改修《太虚化神篇》\n掌握【神念斩】\n掌握【元神法域】','good')
}
function minorBreakthroughBase(index){const i=Number(index)||0;if(i===0)return .82;if(i<=8)return .74;if(i===9)return .48;if(i<=12)return .62;if(i<=17)return .52;if(i<=21)return .43;return .34}
function breakthroughChance(){
 if(state.player.realmIndex>=REALMS.length-1)return 0;const req=majorBreakthroughRequirements();let base=req?req.base:minorBreakthroughBase(state.player.realmIndex);const rootBonus=(root().mult-1)*.18,manualBonus=Math.min(.12,(state.player.manualProf||0)/1800),injuryPenalty=(state.player.injury||0)*.08,pity=(state.player.breakthroughPity||0)/100;return clamp(base+rootBonus+manualBonus+pity-injuryPenalty,req?.kind?.08:.16,req?.kind?.82:.92)
}
function attemptBreakthrough(){
 if(state&&state.flags&&state.flags.dead)return showResult('此世已终','你已经身死道消。','bad');if(state.player.realmIndex>=REALMS.length-1)return showResult('已至当前极限','当前版本已经没有更高境界。');const need=realm().need;if(state.player.progress<need)return showResult('修为未满','当前修为尚未圆满，不能尝试突破。','bad');
 const p=state.player,req=majorBreakthroughRequirements();if(req&&!majorBreakthroughReady(req)){let lack=[];if((p.injury||0)>0)lack.push('必须先养至无伤');if((p.coreEssence||0)<(req.core||0))lack.push('结丹灵髓 '+req.core+'（当前 '+(p.coreEssence||0)+'）');if((p.nascentEssence||0)<(req.nascent||0))lack.push('化婴灵胎 '+req.nascent+'（当前 '+(p.nascentEssence||0)+'）');if((p.deificationEssence||0)<(req.deification||0))lack.push('化神道种 '+req.deification+'（当前 '+(p.deificationEssence||0)+'）');if((p.insight||0)<req.insight)lack.push('悟道点 '+req.insight+'（当前 '+(p.insight||0)+'）');return showResult(req.kind+'准备不足',lack.join('\n'),'bad')}
 const oldRealm=realm().name,chance=breakthroughChance(),days=req?req.days:3;p.breakthroughAttempts++;if(req){p.coreEssence-=req.core||0;p.nascentEssence-=req.nascent||0;p.deificationEssence-=req.deification||0;p.insight-=req.insight}advanceDays(days);if(state.flags.dead)return;
 if(rand()<chance){p.progress=0;p.realmIndex++;p.breakthroughPity=0;p.hp=maxHp();p.qi=maxQi();const newRealm=realm().name,lifeGain=applyRealmLifespanMilestone();if(p.realmIndex===1&&!('火弹术'in p.spells)){p.spells['火弹术']=0;p.spells['御风步']=0;addPersonal('踏入炼气一层后，你终于能够驱使灵力，摸索出了火弹术与御风步。','major')}if(p.realmIndex===10){p.reputation+=8;addWorld(p.name+'成功筑基，寿元与气血根基一并蜕变。','major')}if(p.realmIndex===14){p.reputation+=20;addWorld(p.name+'熬过结丹关，体内丹胚成形，正式踏入结丹境。','major')}if(p.realmIndex===15){p.reputation+=30;addWorld(p.name+'凝成金丹，跻身苍梧一带真正的高阶修士之列。','major')}if(p.realmIndex===19){p.reputation+=80;addWorld(p.name+'碎丹化婴成功，神识与寿元发生质变，正式踏入元婴境。','major')}if(p.realmIndex===23){p.reputation+=150;addWorld(p.name+'炼神化神成功，元神可牵引天地灵机，真正踏入化神之境。','major')}addPersonal('你闭关'+days+'日冲击瓶颈，终于由'+oldRealm+'突破至'+newRealm+'！','major');save();render();showResult('突破成功',oldRealm+' → '+newRealm+'\n气血、灵力恢复至满值\n破境感悟清零'+(lifeGain?'\n寿元上限 +'+lifeGain+'（当前 '+p.lifespan+'）':''),'good')}
 else if(req){const oldProgress=p.progress,isNascent=req.kind==='碎丹化婴',isDeification=req.kind==='炼神化神',ratio=isDeification?rint(35,52)/100:isNascent?rint(42,60)/100:rint(55,72)/100;p.progress=Math.max(0,Math.floor(need*ratio));p.breakthroughPity=Math.min(isDeification?56:isNascent?48:40,(p.breakthroughPity||0)+req.pity);if(isDeification)p.deificationFailures=(p.deificationFailures||0)+1;else if(isNascent)p.nascentFailures=(p.nascentFailures||0)+1;else p.coreFailures=(p.coreFailures||0)+1;p.injury=clamp((p.injury||0)+(isDeification?3:isNascent?2:rint(1,2)),0,3);p.hp=Math.max(1,Math.floor(maxHp()*(isDeification?.10:isNascent?.16:.24)));const loss=rint(req.lifeLoss[0],req.lifeLoss[1]),beforeLife=p.lifespan;p.lifespan=Math.max(age()+5,p.lifespan-loss);const lost=Math.max(0,oldProgress-p.progress),actualLife=Math.max(0,beforeLife-p.lifespan);addPersonal('你冲击'+req.kind+'失败，珍贵积累尽数耗去，根基受创。','bad');save();render();showResult(req.kind+'失败','修为 -'+lost+'\n破境感悟 +'+req.pity+'%（当前 +'+p.breakthroughPity+'%）\n伤势：'+injuryLabel()+(actualLife?'\n寿元 -'+actualLife:'')+'\n本次大境界材料已经消耗。','bad')}
 else{const oldProgress=p.progress,ratio=rint(78,90)/100;p.progress=Math.max(0,Math.floor(need*ratio));p.breakthroughPity=Math.min(32,(p.breakthroughPity||0)+8);let hurt='';if(rand()<.45){const old=p.injury||0;p.injury=clamp(old+1,0,3);p.hp=Math.max(1,Math.floor(p.hp*.72));if(p.injury>old)hurt='，伤势加重至'+injuryLabel()}const lost=Math.max(0,oldProgress-p.progress);addPersonal('你冲击'+oldRealm+'瓶颈失败，修为跌落 '+lost+'，但对瓶颈多了一层理解。','bad');save();render();showResult('突破失败','修为 -'+lost+'\n破境感悟 +8%（当前 +'+p.breakthroughPity+'%）'+hurt+'\n重新修至圆满后可再次尝试。','bad')}
}
function renderBreakthrough(){
 const box=$('breakthroughBox');if(!box)return;const p=state.player,atCap=p.realmIndex>=REALMS.length-1,full=p.progress>=realm().need,req=majorBreakthroughRequirements();let blocks=[];
 if(full&&!atCap){const pct=Math.round(breakthroughChance()*100),next=REALMS[p.realmIndex+1].name,ready=majorBreakthroughReady(req);let text='当前成功率 '+pct+'%。灵根与功法熟练度会影响成功率；越往高境越难，伤势会降低成功率，失败则积累破境感悟。';if(req)text+=' 【'+req.kind+'】额外需要结丹灵髓 '+(req.core||0)+'、化婴灵胎 '+(req.nascent||0)+'、化神道种 '+(req.deification||0)+'、悟道点 '+req.insight+'，耗时 '+req.days+' 日；失败会损伤根基与寿元。';blocks.push('<div class="urgent"><div class="urgent-title">【境界圆满】可尝试突破至 '+esc(next)+'</div><p>'+esc(text)+'</p><div class="urgent-foot"><span>灵髓 '+(p.coreEssence||0)+' · 灵胎 '+(p.nascentEssence||0)+' · 道种 '+(p.deificationEssence||0)+' · 悟道 '+(p.insight||0)+' · 破境感悟 +'+(p.breakthroughPity||0)+'%</span><button class="mini-btn primary" data-breakthrough '+(ready?'':'disabled')+'>尝试突破 · '+(req?req.days:3)+'日</button></div></div>')}
 if(p.realmIndex>=15&&!('金焰剑诀'in p.spells))blocks.push('<div class="urgent"><div class="urgent-title">【金丹传承】你的境界已经压过低阶法术</div><p>前往青云山或古河遗迹，消耗灵石40、悟道点3、古修残片2，可改修《丹霞金章》并掌握金焰剑诀、护体灵罡。</p><div class="urgent-foot"><span>当前地点：'+esc(p.location)+'</span><button class="mini-btn" data-high-inherit>参悟金丹传承</button></div></div>');
 if(p.realmIndex>=23&&!('神念斩'in p.spells))blocks.push('<div class="urgent"><div class="urgent-title">【化神传承】元神已经可以触碰天地道痕</div><p>前往古河遗迹或玄阴禁地，消耗灵石120、悟道点5、古修残片5，可改修《太虚化神篇》并掌握神念斩、元神法域。</p><div class="urgent-foot"><span>当前地点：'+esc(p.location)+'</span><button class="mini-btn" data-spirit-inherit>参悟化神传承</button></div></div>');
 box.innerHTML=blocks.join('');const b=document.querySelector('[data-breakthrough]');if(b)b.onclick=attemptBreakthrough;const h=document.querySelector('[data-high-inherit]');if(h)h.onclick=claimGoldenCoreInheritance;const s=document.querySelector('[data-spirit-inherit]');if(s)s.onclick=claimSpiritTransformationInheritance
}
function renderCorePath(){
 let panel=$('corePathPanel');if(!panel){const page=$('page-character');if(!page)return;panel=document.createElement('section');panel.className='panel';panel.id='corePathPanel';panel.innerHTML='<h2>结丹、金丹、元婴与化神</h2><p class="section-tip">元婴后期开始准备化神道种。元婴圆满后的炼神化神需要更漫长闭关，失败会濒死并损失大量寿元。</p><div id="corePathInfo"></div><div id="corePathActions"></div>';page.appendChild(panel)}const p=state.player,info=$('corePathInfo'),actions=$('corePathActions');if(!info||!actions)return;const req=majorBreakthroughRequirements();info.innerHTML='<div class="kv"><span>当前境界</span><b>'+esc(realm().name)+'</b></div><div class="kv"><span>寿元上限</span><b>'+p.lifespan+'</b></div><div class="kv"><span>结丹灵髓</span><b>'+(p.coreEssence||0)+'</b></div><div class="kv"><span>化婴灵胎</span><b>'+(p.nascentEssence||0)+'</b></div><div class="kv"><span>化神道种</span><b>'+(p.deificationEssence||0)+'</b></div><div class="kv"><span>结丹/金丹失败</span><b>'+(p.coreFailures||0)+' 次</b></div><div class="kv"><span>化婴失败</span><b>'+(p.nascentFailures||0)+' 次</b></div><div class="kv"><span>化神失败</span><b>'+(p.deificationFailures||0)+' 次</b></div>'+(req?'<div class="kv"><span>'+esc(req.kind)+'需求</span><b>灵髓 '+(req.core||0)+' · 灵胎 '+(req.nascent||0)+' · 道种 '+(req.deification||0)+' · 悟道 '+req.insight+' · '+req.days+'日</b></div>':'');let html='';if(p.realmIndex>=12){const here=CORE_REFINING_LOCATIONS.includes(p.location);html+='<div class="section-tip">结丹灵髓：赤霞谷 / 落星矿脉 / 古河遗迹。每份灵草4、兽材2、灵石6，耗时2日。</div><div class="event-actions"><button data-core-craft '+(here?'':'disabled')+'>淬炼结丹灵髓 · 2日</button></div>'}if(p.realmIndex>=17){const here2=NASCENT_REFINING_LOCATIONS.includes(p.location);html+='<div class="section-tip">化婴灵胎：古河遗迹 / 玄阴禁地。每份结丹灵髓1、古修残片2、灵草6、灵石12，耗时3日。</div><div class="event-actions"><button data-nascent-craft '+(here2?'':'disabled')+'>淬炼化婴灵胎 · 3日</button></div>'}if(p.realmIndex>=21){const here3=DEIFICATION_REFINING_LOCATIONS.includes(p.location);html+='<div class="section-tip">化神道种：古河遗迹 / 玄阴禁地。每份化婴灵胎1、古修残片3、兽材4、灵草8、灵石25，耗时4日。</div><div class="event-actions"><button data-deification-craft '+(here3?'':'disabled')+'>淬炼化神道种 · 4日</button></div>'}if(!html)html='<div class="section-tip">达到筑基后期后依次开启结丹、化婴与化神资源准备。</div>';actions.innerHTML=html;const a=actions.querySelector('[data-core-craft]');if(a)a.onclick=craftCoreEssence;const n=actions.querySelector('[data-nascent-craft]');if(n)n.onclick=craftNascentEssence;const d=actions.querySelector('[data-deification-craft]');if(d)d.onclick=craftDeificationEssence
}

function daoSwitchExtra(id){const p=state.player;return p.daoPath!=='none'&&p.daoPath!==id?3:0}
function daoPathCostText(id){const d=DAO_PATHS[id],extra=daoSwitchExtra(id),rows=['灵石'+d.stones,'高阶灵材'+d.rare,'悟道'+(d.insight+extra)];if(d.materials)rows.push('兽材'+d.materials);if(d.relic)rows.push('古修残片'+d.relic);if(d.contribution)rows.push('宗门贡献'+d.contribution);return rows.join(' · ')}
function daoPathReady(id){const d=DAO_PATHS[id],p=state.player;if(!d||p.realmIndex<d.realm||!d.locations.includes(p.location))return false;if(d.sect&&p.sect!==d.sect)return false;return p.spiritStones>=d.stones&&(p.rareMaterials||0)>=d.rare&&(p.insight||0)>=d.insight+daoSwitchExtra(id)&&(p.beastMaterials||0)>=(d.materials||0)&&(p.relicFragments||0)>=(d.relic||0)&&(p.sectContribution||0)>=(d.contribution||0)}
function chooseDaoPath(id){
 const d=DAO_PATHS[id],p=state.player;if(!d)return;if(p.daoPath===id)return showResult('正在主修','你当前主修的就是【'+d.name+'】。');if(p.realmIndex<d.realm)return showResult('境界不足','至少达到'+REALMS[d.realm].name+'才能正式立下主修道途。','bad');if(!d.locations.includes(p.location))return showResult('传承不在此地','【'+d.name+'】需要前往'+d.locations.join(' / ')+'参悟。','bad');if(d.sect&&p.sect!==d.sect)return showResult('传承受限','【'+d.name+'】属于青云宗剑脉，需先成为青云宗弟子。','bad');const extra=daoSwitchExtra(id);if(!daoPathReady(id))return showResult('立道资源不足','需要：'+daoPathCostText(id)+'。','bad');
 p.spiritStones-=d.stones;p.rareMaterials-=d.rare;p.insight-=d.insight+extra;p.beastMaterials-=d.materials||0;p.relicFragments-=d.relic||0;p.sectContribution-=d.contribution||0;if(p.daoPath!=='none'&&p.daoPath!==id){p.daoMastery=Math.floor((p.daoMastery||0)*.5);p.daoSwitches=(p.daoSwitches||0)+1}p.daoPath=id;p.manual=d.manual;p.manualProf=Math.max(20,Math.floor((p.manualProf||0)*.35));if(!(d.spell in p.spells))p.spells[d.spell]=0;p.hp=Math.min(p.hp,maxHp());p.qi=Math.min(p.qi,maxQi());addPersonal('你正式立下主修道途【'+d.name+'】，改修《'+d.manual+'》并掌握【'+d.spell+'】。','major');save();render();showResult('道途已定','主修：'+d.name+'\n功法：《'+d.manual+'》\n绝学：'+d.spell+(extra?'\n转修额外消耗悟道 '+extra:'')+'。','good')
}
function onDaoCombatWin(e){const d=daoPathDef();if(!d)return;const bonus=d.locations.includes(state.player.location)?3:1;state.player.daoMastery=(state.player.daoMastery||0)+bonus;if(bonus>1)addPersonal('你在与自身道途契合之地经历实战，【'+d.name+'】熟练度 +'+bonus+'。','good')}
function daoCombatButtonHtml(){const d=daoPathDef();if(!d)return '';const sp=SPELLS[d.spell],known=d.spell in state.player.spells,disabled=!known||combat.playerQi<sp.qi;return '<button data-combat="dao" '+(disabled?'disabled':'')+'>'+d.spell+' · '+sp.qi+'灵力</button>'}
function useDaoCombatSkill(e){const d=daoPathDef();if(!d)return false;const sp=SPELLS[d.spell];if(!(d.spell in state.player.spells)||combat.playerQi<sp.qi)return false;const p=state.player,prof=p.spells[d.spell]||0,sup=realmSuppressionMultiplier(p.realmIndex,e.realm||0),sig=daoSignatureMultiplier();combat.playerQi-=sp.qi;let dmg=0;
 if(d.id==='sword'){const one=Math.max(1,Math.floor((sp.power+rint(16,28)+p.realmIndex*6+gearAtk()*.7+prof/12)*sup*gearSpellMultiplier()*sig));const two=Math.max(1,Math.floor(one*(.72+rand()*.18)));dmg=one+two;combat.enemyHp-=dmg;combat.logs.push('飞剑一前一后掠过，御剑连斩共造成 '+dmg+' 点伤害。')}
 else if(d.id==='flame'){dmg=Math.max(1,Math.floor((sp.power+rint(22,38)+p.realmIndex*8+prof/10)*sup*gearSpellMultiplier()*daoSpellMultiplier()*sig));combat.enemyHp-=dmg;combat.burn=Math.max(combat.burn||0,3);combat.logs.push('焚脉真火钻入经脉，造成 '+dmg+' 点伤害，并留下三层真火灼烧。')}
 else if(d.id==='body'){dmg=Math.max(1,Math.floor((sp.power+rint(10,22)+p.realmIndex*5+maxHp()*.055+gearAtk()+gearDef()*1.6+prof/15)*sup*sig));combat.enemyHp-=dmg;combat.bodyGuard=Math.max(combat.bodyGuard||0,2);combat.logs.push('你以肉身撞出崩山式，造成 '+dmg+' 点伤害，并稳住护体架势。')}
 else{dmg=Math.max(1,Math.floor((sp.power+rint(24,42)+p.realmIndex*9+prof/9)*sup*gearSpellMultiplier()*daoSpellMultiplier()*sig));combat.enemyHp-=dmg;combat.soulSeal=Math.max(combat.soulSeal||0,3);combat.logs.push('摄魂印震入识海，造成 '+dmg+' 点伤害，并封压对方神魂。')}
 p.spells[d.spell]=prof+6;p.daoMastery=(p.daoMastery||0)+3;return true
}
function renderDaoPath(){
 let panel=$('daoPathPanel');if(!panel){const page=$('page-character');if(!page)return;panel=document.createElement('section');panel.className='panel';panel.id='daoPathPanel';panel.innerHTML='<h2>主修道途</h2><p class="section-tip">结丹后可选择剑修、火法、体修或神识流。V2.2 起，道途还会改变地域机缘、NPC同道反馈与部分势力待遇。</p><div id="daoPathInfo"></div><div id="daoPathActions"></div>';page.appendChild(panel)}const p=state.player,d=daoPathDef(),info=$('daoPathInfo'),actions=$('daoPathActions');if(!info||!actions)return;const renown=d?daoRenownValue(d.id):0,resonance=d?(DAO_WORLD_LOCATIONS[d.id]||[]).join(' / '):'—';info.innerHTML='<div class="kv"><span>当前主修</span><b>'+(d?d.name:'尚未立道')+'</b></div><div class="kv"><span>道途熟练</span><b>'+(p.daoMastery||0)+'</b></div><div class="kv"><span>当前道途名望</span><b>'+renown+'</b></div><div class="kv"><span>已遇道途机缘</span><b>'+(p.daoEncounters||0)+' 次</b></div><div class="kv"><span>共鸣地域</span><b>'+resonance+'</b></div><div class="kv"><span>转修次数</span><b>'+(p.daoSwitches||0)+'</b></div>'+(d?'<div class="skill-card"><div class="skill-head"><b>'+d.name+'</b><span>'+d.spell+'</span></div><div class="skill-desc">'+d.desc+'<br>绝学倍率：×'+daoSignatureMultiplier().toFixed(2)+' · 同道NPC会识别此路数</div></div>':'');actions.innerHTML=Object.values(DAO_PATHS).map(x=>{const current=p.daoPath===x.id,ready=daoPathReady(x.id);return '<div class="skill-card"><div class="skill-head"><b>【'+x.name+'】</b><span>'+x.locations.join(' / ')+'</span></div><div class="skill-desc">'+x.desc+'<br>立道：'+daoPathCostText(x.id)+'<br>世界共鸣：'+(DAO_WORLD_LOCATIONS[x.id]||[]).join(' / ')+'</div></div><div class="event-actions"><button data-dao-path="'+x.id+'" '+(current||!ready?'disabled':'')+'>'+(current?'当前主修':p.daoPath==='none'?'立下此道':'转修此道')+'</button></div>'}).join('');actions.querySelectorAll('[data-dao-path]').forEach(b=>b.onclick=()=>chooseDaoPath(b.dataset.daoPath))
}

function locationProfile(){return LOCATIONS[state.player.location]||LOCATIONS['青石村']}
function locationDangerText(l){const d=l?.danger||0;return d>=.65?'禁地':d>=.55?'凶险':d>=.45?'高危':d>=.34?'危险':d>=.24?'谨慎':'安稳'}
function secretActivityText(l){const x=l?.secret||0;return x>=1.8?'极活跃':x>=1.25?'活跃':x>=.75?'较多':'稀少'}
function gather(){if(livingActionGuard())return;advanceDays(1);const l=locationProfile(),n=rint(1,3)+(l.herb||0);state.player.herbs+=n;addDiligence(2);addPersonal(`你在${state.player.location}附近采到 ${n} 株可用灵草。当地特产：${l.specialty}。`,'good');save();render();showResult('采集灵草',`灵草 +${n}\n区域：${state.player.location} · ${locationDangerText(l)}\n特产：${l.specialty}`,'good')}
function work(){if(livingActionGuard())return;advanceDays(1);const l=locationProfile(),range=l.work||[1,2],n=rint(range[0],range[1]);state.player.spiritStones+=n;addDiligence(1);addPersonal(`你在${state.player.location}谋生一日，换得 ${n} 块灵石。`);save();render();showResult('谋生换钱',`灵石 +${n}\n当地主要资源：${l.specialty}`,'good')}
function rest(){if(livingActionGuard())return;advanceDays(1);const before=state.player.hp,old=state.player.injury||0;state.player.hp=Math.min(maxHp(),state.player.hp+Math.ceil(maxHp()*.52));state.player.qi=maxQi();if(state.player.injury>0)state.player.injury--;addDiligence(1);addPersonal('你闭门休息了一整日，气血与灵力恢复。'+(old>state.player.injury?'伤势有所缓解。':''),'good');save();render();showResult('闭门休整',`气血 +${state.player.hp-before}\n灵力恢复至满值${old>state.player.injury?`\n伤势：${['无伤','轻伤','重伤','濒死'][old]} → ${injuryLabel()}`:''}`,'good')}
function rumor(){if(livingActionGuard())return;advanceDays(1);addDiligence(1);let msg;if(state.major.recruit?.status==='announced')msg='青云宗收徒之日临近，附近不少少年已经启程。';else if(state.world.beastPressure>68)msg='黑风岭里的妖兽越来越躁动，山脚猎户已经不敢深入。';else msg=pick(['临江城坊市最近灵米涨价。','有人说血刀门在暗中招揽散修。','青云山近日有剑光划过云海。','一个散修在黑风岭捡到残破储物袋，一夜暴富。']);addWorld(msg);addPersonal(`你花了一天四处打听：${msg}`);save();render();showResult('打听消息',msg)}
function explore(){if(livingActionGuard())return;advanceDays(1);addDiligence(2);const l=locationProfile(),danger=l.danger||.20,x=rand();if(x<danger){startCombat(weightedEnemy());return}if(x<danger+(l.eventRate||.08)){startRegionalEvent();return}if(x<danger+(l.eventRate||.08)+.22){startMinorEvent();return}if(x<danger+(l.eventRate||.08)+.38){const range=l.find||[1,4],n=rint(range[0],range[1]);state.player.spiritStones+=n;addPersonal(`你在${state.player.location}一处隐蔽角落找到 ${n} 块灵石。`,'good');save();render();showResult('意外收获',`灵石 +${n}\n此地探索危险：${locationDangerText(l)}`,'good');return}addPersonal(`你在${state.player.location}转了一日，只记下了附近地形与人流。`);save();render();showResult('区域探索',`这一日没有额外收获。\n${state.player.location}：${l.specialty}`)}
function startRegionalEvent(){
 const l=locationProfile(),kind=l.eventKind||'stones',name=state.player.location;let text='';if(daoWorldEventAvailable()&&rand()<.55){startDaoWorldEvent();return}
 if(kind==='herb'){const n=rint(1,2)+(l.herb||0);state.player.herbs+=n;text='顺着当地修士留下的采集痕迹，你额外找到 '+n+' 株灵草。';showResult('地域机缘',text+'\n灵草 +'+n,'good')}
 else if(kind==='materials'){const n=rint(1,2);state.player.beastMaterials+=n;text='你在险地边缘找到可用于锻造的残骨与灵材，共 '+n+' 份。';showResult('地域机缘',text+'\n兽材 +'+n,'good')}
 else if(kind==='manual'){const n=rint(5,12);state.player.manualProf+=n;text='你旁听同道演法，对自身行功路线多了几分理解。';showResult('山门见闻',text+'\n功法熟练度 +'+n,'good')}
 else if(kind==='relic'){state.player.relicFragments+=1;text='断壁下露出一枚带有古老纹路的残片。';showResult('遗迹残物',text+'\n古修残片 +1','good')}
 else if(kind==='insight'){if(rand()<.35){state.player.insight+=1;text='阴煞与灵机交错的一瞬，你忽然抓住一缕感悟。';showResult('禁地悟道',text+'\n悟道点 +1','good')}else{const n=rint(10,22);state.player.manualProf+=n;text='你从阴煞流向中悟出一些运气法门。';showResult('禁地见闻',text+'\n功法熟练度 +'+n,'good')}}
 else{const range=l.find||[1,4],n=rint(range[0],range[1]);state.player.spiritStones+=n;text='当地商旅与修士流动频繁，你抓住一桩短差赚到 '+n+' 块灵石。';showResult('地域机缘',text+'\n灵石 +'+n,'good')}
 addPersonal('【地域见闻】'+name+'：'+text,'good');save();render()
}
function startMinorEvent(){
 const type=pick(['wounded','merchant','cave','npc']);
 if(type==='wounded'){
  const npc=pick(state.npcs.filter(n=>n.alive));npc.known=true;showChoice('林间求救',`你发现${npc.name}靠在树下，衣襟染血，远处似乎还有追兵。`,[
   {label:'拿一株灵草救人',disabled:state.player.herbs<1,fn:()=>{state.player.herbs--;npc.relation=clamp(npc.relation+12,-100,100);state.player.reputation+=2;addPersonal(`你救下${npc.name}，这份人情被对方牢牢记住。`,'good');showResult('救人一命',`${npc.name} 对你的关系 +12\n声望 +2`,'good')}},
   {label:'趁火打劫',fn:()=>{const s=rint(2,5);state.player.spiritStones+=s;npc.grudge=clamp(npc.grudge+25,0,100);npc.relation=clamp(npc.relation-20,-100,100);addPersonal(`你从重伤的${npc.name}身上拿走${s}块灵石。对方看你的眼神，你不会忘。`,'bad');showResult('趁火打劫',`灵石 +${s}\n${npc.name} 仇恨 +25`,'bad')}},
   {label:'不惹麻烦',fn:()=>{addPersonal(`你没有卷入${npc.name}的麻烦。`);showResult('转身离开','你保住了自己，也没有得到任何东西。')}}]);
 }else if(type==='merchant')showChoice('落魄散修',`一名散修急着离开此地，愿用 2 块灵石卖你一册《青云引气诀》抄本。`,[
  {label:'买下功法（2灵石）',disabled:state.player.spiritStones<2,fn:()=>{state.player.spiritStones-=2;state.player.manual='青云引气诀';state.player.manualProf=0;addPersonal('你买下《青云引气诀》，立刻换掉了原先粗浅的吐纳法。','major');showResult('更换功法','获得《青云引气诀》\n当前修炼效率提高。','good')}},
  {label:'算了',fn:()=>showResult('没有交易','你没有花这笔灵石。')}]);
 else if(type==='cave')showChoice('岩壁后的洞口',`你发现一处被藤蔓遮住的狭小山洞。里面吹出凉风，也隐约有腥气。`,[
  {label:'进去看看',fn:()=>{if(rand()<.5){const s=rint(3,7);state.player.spiritStones+=s;showResult('废弃洞府',`你找到前人留下的灵石 ${s} 块。`,'good')}else{startCombat({...ENEMIES[2]})}}},
  {label:'谨慎离开',fn:()=>showResult('谨慎离开','未知的洞府也可能是坟墓。你没有冒险。')}]);
 else {const npc=pick(state.npcs.filter(n=>n.alive));npc.known=true;showChoice('偶遇同道',`你在路上遇见${npc.name}（${npc.faction}，${REALMS[npc.realmIndex].name}）。对方也在打量你。`,[
  {label:'上前攀谈',fn:()=>{npc.relation=clamp(npc.relation+rint(4,9),-100,100);showResult('结识同道',`${npc.name} 对你的关系有所提升。`,'good')}},
  {label:'点头而过',fn:()=>showResult('擦肩而过','你们彼此记住了脸，却没有深谈。')}]);}
}
function showChoice(title,text,choices){let html=`<h2>${esc(title)}</h2><p>${esc(text)}</p><div class="modal-actions">`;choices.forEach((c,i)=>{html+=`<button data-choice="${i}" ${c.disabled?'disabled':''}>${esc(c.label)}</button>`});html+='</div>';openModal(html);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const c=choices[+b.dataset.choice];if(c.disabled)return;closeModal();c.fn();save();render()})}
function startCombat(enemyTemplate){const e=JSON.parse(JSON.stringify(enemyTemplate));if(!e.reward)e.reward={stones:[0,0],herbs:[0,0],rep:0};if(!e.reward.herbs)e.reward.herbs=[0,0];const ally=findNpcBattleAlly(e);combat={enemy:e,enemyHp:e.hp,playerHp:state.player.hp,playerQi:state.player.qi,defending:false,evade:0,guard:0,domain:0,weaken:0,burn:0,bodyGuard:0,soulSeal:0,round:1,allyNpcId:ally?ally.id:null,allyTurns:ally?3:0,allyCounted:false,cooldowns:{},statuses:{},logs:['你遭遇了'+e.name+'。危险判断：'+dangerLabel(e)+'。']};if(ally)combat.logs.push(ally.name+'见你遇敌，决定并肩助阵。');renderCombat()}
function renderCombat(){const e=combat.enemy,pPct=clamp(combat.playerHp/maxHp()*100,0,100),ePct=clamp(combat.enemyHp/e.hp*100,0,100),wind='御风步'in state.player.spells;let html=`<h2>遭遇战 · 第${combat.round}回合</h2><div class="combatants"><div class="fighter"><b>${esc(state.player.name)}</b><div class="hp">${realm().name} · 气血 ${combat.playerHp}/${maxHp()} · 灵力 ${combat.playerQi}/${maxQi()}</div><div class="bar"><i style="width:${pPct}%"></i></div></div><div class="vs">VS</div><div class="fighter"><b>${esc(e.name)}</b><div class="hp">${esc(e.kind||'敌人')} · ${REALMS[Math.min(e.realm||0,REALMS.length-1)].name} · ${dangerLabel(e)}</div><div class="hp">气血 ${Math.max(0,combat.enemyHp)}/${e.hp}</div><div class="bar"><i style="width:${ePct}%"></i></div></div></div><div class="combat-log">${combat.logs.slice(-9).map(x=>`• ${esc(x)}<br>`).join('')}</div><div class="modal-actions two"><button data-combat="attack">拳脚攻击</button><button data-combat="spell" ${!('火弹术'in state.player.spells)||combat.playerQi<SPELLS['火弹术'].qi?'disabled':''}>火弹术</button><button data-combat="wind" ${!wind||combat.playerQi<SPELLS['御风步'].qi?'disabled':''}>御风步</button><button data-combat="golden" ${!('金焰剑诀'in state.player.spells)||combat.playerQi<SPELLS['金焰剑诀'].qi?'disabled':''}>金焰剑诀</button><button data-combat="guard" ${!('护体灵罡'in state.player.spells)||combat.playerQi<SPELLS['护体灵罡'].qi?'disabled':''}>护体灵罡</button><button data-combat="divine" ${!('神念斩'in state.player.spells)||combat.playerQi<SPELLS['神念斩'].qi?'disabled':''}>神念斩</button><button data-combat="domain" ${!('元神法域'in state.player.spells)||combat.playerQi<SPELLS['元神法域'].qi?'disabled':''}>元神法域</button>${daoCombatButtonHtml()}<button data-combat="defend">防御</button><button data-combat="flee">逃跑</button></div>`;openModal(html,false);document.querySelectorAll('[data-combat]').forEach(b=>b.onclick=()=>combatAction(b.dataset.combat))}
function combatAction(a){if(!combat||state.flags.dead)return;const e=combat.enemy;combat.defending=false;if(a==='attack'){const prof=state.player.spells['基础拳脚']||0,baseDmg=rint(7,12)+state.player.realmIndex*3+Math.floor(prof/35)+Math.floor(state.player.manualProf/80)+gearAtk(),dmg=Math.max(1,Math.floor(baseDmg*realmSuppressionMultiplier(state.player.realmIndex,e.realm||0)*daoMeleeMultiplier()));combat.enemyHp-=dmg;state.player.spells['基础拳脚']=prof+2;combat.logs.push(`你近身攻出一击，造成 ${dmg} 点伤害。`)}else if(a==='spell'){const sp=SPELLS['火弹术'];if(!('火弹术'in state.player.spells)||combat.playerQi<sp.qi)return;combat.playerQi-=sp.qi;const prof=state.player.spells['火弹术']||0,baseDmg=sp.power+rint(2,8)+state.player.realmIndex*4+Math.floor(prof/14),dmg=Math.max(1,Math.floor(baseDmg*realmSuppressionMultiplier(state.player.realmIndex,e.realm||0)*gearSpellMultiplier()*daoSpellMultiplier()));combat.enemyHp-=dmg;state.player.spells['火弹术']=prof+4;combat.logs.push(`火弹炸开，造成 ${dmg} 点伤害。`)}else if(a==='wind'){const sp=SPELLS['御风步'];if(!('御风步'in state.player.spells)||combat.playerQi<sp.qi)return;combat.playerQi-=sp.qi;const prof=state.player.spells['御风步']||0;state.player.spells['御风步']=prof+3;combat.evade=2;combat.logs.push('你运转御风步，接下来两回合更容易闪开攻击。')}else if(a==='golden'){const sp=SPELLS['金焰剑诀'];if(!('金焰剑诀'in state.player.spells)||combat.playerQi<sp.qi)return;combat.playerQi-=sp.qi;const prof=state.player.spells['金焰剑诀']||0,baseDmg=sp.power+rint(18,32)+state.player.realmIndex*7+Math.floor(prof/10),dmg=Math.max(1,Math.floor(baseDmg*realmSuppressionMultiplier(state.player.realmIndex,e.realm||0)*gearSpellMultiplier()*daoSpellMultiplier()));combat.enemyHp-=dmg;state.player.spells['金焰剑诀']=prof+5;combat.logs.push('金焰剑罡贯空而过，造成 '+dmg+' 点伤害。')}else if(a==='guard'){const sp=SPELLS['护体灵罡'];if(!('护体灵罡'in state.player.spells)||combat.playerQi<sp.qi)return;combat.playerQi-=sp.qi;state.player.spells['护体灵罡']=(state.player.spells['护体灵罡']||0)+4;combat.guard=3;combat.logs.push('护体灵罡展开，接下来三次受击显著减伤。')}else if(a==='divine'){const sp=SPELLS['神念斩'];if(!('神念斩'in state.player.spells)||combat.playerQi<sp.qi)return;combat.playerQi-=sp.qi;const prof=state.player.spells['神念斩']||0,baseDmg=sp.power+rint(40,70)+state.player.realmIndex*12+Math.floor(prof/8),dmg=Math.max(1,Math.floor(baseDmg*realmSuppressionMultiplier(state.player.realmIndex,e.realm||0)*gearSpellMultiplier()*daoSpellMultiplier()));combat.enemyHp-=dmg;combat.weaken=2;state.player.spells['神念斩']=prof+6;combat.logs.push('神念如刃斩入识海，造成 '+dmg+' 点伤害，并扰乱对方神识。')}else if(a==='domain'){const sp=SPELLS['元神法域'];if(!('元神法域'in state.player.spells)||combat.playerQi<sp.qi)return;combat.playerQi-=sp.qi;state.player.spells['元神法域']=(state.player.spells['元神法域']||0)+5;combat.domain=3;combat.logs.push('元神法域展开，接下来三次受击都会被神识领域削弱。')}else if(a==='dao'){if(!useDaoCombatSkill(e))return}else if(a==='defend'){combat.defending=true;combat.logs.push('你收敛气息，架势转守。')}else if(a==='flee'){const diff=(e.realm||0)-state.player.realmIndex,windBonus=('御风步'in state.player.spells)?Math.min(.30,(state.player.spells['御风步']||0)/180):0,chance=clamp(.40+windBonus-diff*.08,.12,.78);if(rand()<chance){state.player.hp=Math.max(1,combat.playerHp);state.player.qi=combat.playerQi;addPersonal(`你从${e.name}手中脱身。`);combat=null;save();render();closeModal();showResult('成功脱身','你没有继续纠缠。');return}else combat.logs.push('你试图脱身，但被对方逼了回来。')}if(combat.enemyHp<=0){finishCombat(true);return}npcBattleAllyTurn(e);if(combat.enemyHp<=0){finishCombat(true);return}if(combat.burn>0){const dot=Math.max(1,Math.floor((18+state.player.realmIndex*5+(state.player.daoMastery||0)/20)*gearSpellMultiplier()*daoSpellMultiplier()));combat.enemyHp-=dot;combat.burn--;combat.logs.push('焚脉真火继续灼烧，造成 '+dot+' 点伤害。');if(combat.enemyHp<=0){finishCombat(true);return}}let dodged=false;if(combat.evade>0){combat.evade--;const prof=state.player.spells['御风步']||0;if(rand()<clamp(.34+prof/500,0,.62)){dodged=true;combat.logs.push(`御风步生效，你避开了${e.name}的反击。`)}}if(!dodged){let edmg=rint(e.atk[0],e.atk[1]);if(combat.enemyHp/e.hp<.32&&rand()<.30){edmg=Math.ceil(edmg*1.35);combat.logs.push(`${e.name}在伤势刺激下突然暴起！`)}edmg=Math.max(1,Math.floor(edmg*realmSuppressionMultiplier(e.realm||0,state.player.realmIndex)*daoIncomingMultiplier()));if(combat.weaken>0){combat.weaken--;edmg=Math.ceil(edmg*.78);combat.logs.push('神念斩残留的神识扰动削弱了对方反击。')}if(combat.soulSeal>0){combat.soulSeal--;edmg=Math.ceil(edmg*.58);combat.logs.push('摄魂印封压神魂，对方反击明显迟滞。')}if(combat.bodyGuard>0){combat.bodyGuard--;edmg=Math.ceil(edmg*.62);combat.logs.push('炼体架势卸去了大半冲击。')}if(combat.domain>0){combat.domain--;edmg=Math.ceil(edmg*.62);combat.logs.push('元神法域扭曲灵机，削去了大半冲击。')}if(combat.guard>0){combat.guard--;edmg=Math.ceil(edmg*.55);combat.logs.push('护体灵罡削去了大半冲击。')}if(combat.defending)edmg=Math.ceil(edmg*.52);edmg=Math.max(1,edmg-Math.floor(state.player.realmIndex*.8)-gearDef());combat.playerHp-=edmg;combat.logs.push(`${e.name}反击，造成 ${edmg} 点伤害。`)}if(combat.playerHp<=0){finishCombat(false);return}combat.round++;renderCombat()}
function highTierMaterialDrop(e){const r=e?.realm||0;if(r>=23)return rint(1,2);if(r>=19)return rand()<.65?1:0;if(r>=15)return rand()<.35?1:0;return 0}
function finishCombat(win){const e=combat.enemy;if(win){const stones=rint(e.reward.stones?.[0]||0,e.reward.stones?.[1]||0),herbs=rint(e.reward.herbs?.[0]||0,e.reward.herbs?.[1]||0),core=rint(e.reward.core?.[0]||0,e.reward.core?.[1]||0),nascent=rint(e.reward.nascent?.[0]||0,e.reward.nascent?.[1]||0),deification=rint(e.reward.deification?.[0]||0,e.reward.deification?.[1]||0),rare=e.nonLethal?0:highTierMaterialDrop(e);state.player.spiritStones+=stones;state.player.herbs+=herbs;state.player.coreEssence=(state.player.coreEssence||0)+core;state.player.nascentEssence=(state.player.nascentEssence||0)+nascent;state.player.deificationEssence=(state.player.deificationEssence||0)+deification;state.player.rareMaterials=(state.player.rareMaterials||0)+rare;state.player.reputation+=e.reward.rep||0;if(core)addPersonal('你从'+e.name+'身上取得结丹灵髓 '+core+' 份。','major');if(nascent)addPersonal('你从'+e.name+'残留的元神精华中取得化婴灵胎 '+nascent+' 份。','major');if(deification)addPersonal('你从'+e.name+'残留的神识道痕中取得化神道种 '+deification+' 份。','major');if(rare)addPersonal('你从'+e.name+'身上取得可用于高阶炼丹炼器的【高阶灵材】 '+rare+' 份。','major');state.player.hp=Math.max(1,combat.playerHp);state.player.qi=combat.playerQi;state.player.battleWins++;if(!e.nonLethal)state.player.kills++;onSectCombatWin(e);onSectAssessmentResult(true,e);onSectInternalCombatResult(true,e);onGearCombatWin(e);onDaoCombatWin(e);onSecretRealmCombatWin(e);onFactionWarCombatWin(e);onFactionContractCombatWin(e);addDiligence(3);addPersonal(`你击败${e.name}。${stones?`获得${stones}块灵石。`:''}${herbs?`获得${herbs}株灵草。`:''}`,'good');combat=null;closeModal();save();render();showResult('战斗胜利',`${stones?`灵石 +${stones}\n`:''}${herbs?`灵草 +${herbs}\n`:''}${e.reward.rep?`声望 +${e.reward.rep}\n`:''}战绩 ${state.player.battleWins}胜 ${state.player.battleLosses}败`,'good')}else{state.player.battleLosses++;onSectAssessmentResult(false,e);onSectInternalCombatResult(false,e);const risk=deathRisk(e);if(!e.nonLethal&&risk>0&&rand()<risk){state.flags.dead=true;state.player.hp=0;state.player.qi=0;addPersonal(`你败在${e.name}手中，伤势过重，身死道消。`,'bad');combat=null;closeModal();save();render();showResult('身死道消',`敌人：${e.name}\n此世已经结束。`,'bad');return}const diff=Math.max(0,(e.realm||0)-state.player.realmIndex),add=diff>=2?2:1;state.player.injury=clamp((state.player.injury||0)+add,0,3);const lost=e.nonLethal?0:Math.min(state.player.spiritStones,rint(0,Math.max(2,diff+1)));state.player.spiritStones-=lost;state.player.hp=Math.max(1,Math.ceil(maxHp()*(state.player.injury>=3?.18:.30)));state.player.qi=0;addPersonal(`你败在${e.name}手下，拖着${injuryLabel()}逃了回来。`,'bad');combat=null;closeModal();save();render();showResult('战斗失败',`你侥幸活了下来。\n当前伤势：${injuryLabel()}${lost?`\n遗失灵石 ${lost}`:''}\n建议先闭门休整。`,'bad')}}
function majorDef(id,title,location,announce,start,end,text){return{id,title,location,announce,start,end,text}}
const MAJORS=[majorDef('recruit','青云宗开山收徒','青云山',4,8,12,'青云宗将在山门外测验灵根。资质出众者可直接入门，普通人也可能得到杂役弟子的机会。'),majorDef('cave','苍梧古洞现世','黑风岭',25,30,36,'黑风岭深处出现古修洞府霞光，各方散修已经闻风而动。')];
function getMajor(id){return state.major[id]}
function ensureMajor(d,status){if(!state.major[d.id])state.major[d.id]={...d,status,participated:false};return state.major[d.id]}
function updateMajorEvents(){const dn=dayNumber();for(const d of MAJORS){if(dn>=d.announce&&!state.major[d.id]){ensureMajor(d,'announced');addWorld(`【天下大事】${d.title}：${d.text}`,'major')}const m=state.major[d.id];if(!m)continue;if(dn>=d.start&&dn<=d.end&&!m.participated&&m.status!=='ended')m.status='active';if(dn>d.end&&!m.participated&&m.status!=='ended'){m.status='ended';autoResolveMajor(m)}}
 if(state.world.beastPressure>=74&&!state.major.beast){const start=dayNumber()+2;state.major.beast={id:'beast',title:'黑风岭兽潮','location':'黑风岭',announce:dayNumber(),start,end:start+5,text:'黑风岭群兽躁动，青石镇已向附近修士求援。',status:'announced',participated:false};addWorld('【紧急大事】黑风岭兽潮将至！青石镇向四方修士求援。','major')}
 const b=state.major.beast;if(b){if(dayNumber()>=b.start&&dayNumber()<=b.end&&!b.participated&&b.status!=='ended')b.status='active';if(dayNumber()>b.end&&!b.participated&&b.status!=='ended'){b.status='ended';autoResolveMajor(b)}}}
function autoResolveMajor(m){if(m.id==='recruit'){addWorld('青云宗本次收徒结束。数十名少年入门，各自命运自此分流。','major')}else if(m.id==='beast'){const win=state.world.qingyunPower+rint(-15,15)>state.world.beastPressure;if(win){state.world.beastPressure=38;addWorld('青云宗与附近散修联手压下兽潮，青石镇保住了。','major')}else{state.world.casualties+=rint(80,250);state.world.beastPressure=55;addWorld(`兽潮冲破防线，青石镇死伤惨重。已记录死亡 ${state.world.casualties} 人。`,'bad')}}else if(m.id==='cave'){const npc=pick(state.npcs.filter(n=>n.alive));npc.known=true;npc.realmIndex=Math.min(npc.realmIndex+1,8);addWorld(`${m.title}关闭。传闻${npc.name}在洞府中获得机缘，修为大进。`,'major')}}
function participateMajor(id){const m=state.major[id];if(!m||m.status!=='active')return showResult('无法参与','这个事件现在并不处于可参与阶段。','bad');if(state.player.location!==m.location)return showResult('路途未至',`需要先前往【${m.location}】。事件不会等你。`,'bad');m.participated=true;m.status='ended';if(id==='recruit'){if(root().mult>=1.25||state.player.realmIndex>=1){state.player.manual='青云引气诀';state.player.manualProf=Math.max(10,state.player.manualProf);state.player.reputation+=6;joinQingyunSect();addPersonal('你通过青云宗测验，被收入外门，并得到《青云引气诀》。','major');showResult('青云宗收徒',`你通过测试，成为青云宗外门弟子。\n获得《青云引气诀》\n声望 +6`,'good')}else{state.player.reputation+=2;addPersonal('你的灵根并不出众，但你在试炼中的坚持被执事记住，得到一本《青云引气诀》抄本。','good');state.player.manual='青云引气诀';showResult('青云宗收徒',`没有一步登天，但你拿到了真正的修仙功法。\n获得《青云引气诀》`,'good')}}
 else if(id==='beast'){startCombat({name:'兽潮中的铁背狼妖',realm:1,hp:92,atk:[10,17],reward:{stones:[4,8],rep:6},weight:1});state.world.beastPressure=Math.max(30,state.world.beastPressure-18)}
 else if(id==='cave'){const gain=rint(35,70);state.player.progress=Math.min(realm().need,state.player.progress+gain);state.player.spiritStones+=rint(4,9);state.player.reputation+=3;addPersonal('你闯入苍梧古洞，在残破石室里得到一缕精纯灵气与散落灵石。','major');showResult('古洞机缘',`修为 +${gain}\n灵石有所增加\n声望 +3`,'good')}save();render()}
function travel(to,routeId=null){
 if(state?.flags?.dead)return showResult('此世已终','你已经身死道消。','bad');const from=state.player.location,route=getTravelRoute(from,to,routeId);if(!route)return showResult('道路不通','当前没有从【'+from+'】直达【'+to+'】的路线。','bad');if((route.fee||0)>state.player.spiritStones)return showResult('路费不足','选择【'+route.name+'】需要路费 '+route.fee+' 块灵石。','bad');
 const risk=effectiveRouteRisk(route);if(route.fee)state.player.spiritStones-=route.fee;advanceDays(route.days);if(state.flags.dead)return;state.player.location=to;addDiligence(1);addPersonal('你从'+from+'沿【'+route.name+'】赶路 '+route.days+' 日，抵达'+to+'。');const outcome=resolveTravelEncounter(route,from,to,risk);save();render();if(outcome.combat)return;showResult('行旅抵达',from+' → '+to+'\n路线：'+route.name+'\n耗时 '+route.days+' 日'+(route.fee?'\n路费 -'+route.fee+' 灵石':'')+'\n预计风险 '+Math.round(risk*100)+'%\n'+outcome.text,outcome.type||'')
}
function spendInsight(type){if(state.player.insight<1)return showResult('悟道点不足','悟道点需要通过论道、遗迹、秘境、丹药或特殊机缘获得。','bad');state.player.insight--;if(type==='cultivate'){const n=Math.max(25,Math.floor(realm().need*.012));state.player.progress=Math.min(realm().need,state.player.progress+n);addPersonal('你抓住一瞬顿悟，修为推进 '+n+'。','good');showResult('顿悟修为','修为 +'+n,'good')}else if(type==='manual'){state.player.manualProf+=40;addPersonal('你对《'+state.player.manual+'》有了新的领悟。','good');showResult('顿悟功法','《'+state.player.manual+'》熟练度 +40','good')}else{const known=Object.keys(state.player.spells).filter(x=>x!=='基础拳脚');if(!known.length){state.player.insight++;return showResult('暂无法术','踏入炼气一层后再来。','bad')}const s=known[0];state.player.spells[s]+=40;addPersonal('你顿悟了'+s+'。','good');showResult('顿悟法术',s+' 熟练度 +40','good')}save();render()}

