function isSectMember(){return state.player.sect==='青云宗'}
function sectRankIndex(rank=state.player.sectRank){const i=SECT_RANKS.indexOf(rank);return i<0?0:i}
function ensureSectCareerShape(){const p=state.player;if(p.sectMentor===undefined)p.sectMentor=null;if(p.sectMentorBond==null)p.sectMentorBond=0;if(p.sectLastMentorDay==null)p.sectLastMentorDay=0;if(p.sectAssessmentLevel==null)p.sectAssessmentLevel=0;if(p.sectLastAssessmentDay==null)p.sectLastAssessmentDay=0;if(p.sectSeniorTasksCompleted==null)p.sectSeniorTasksCompleted=0}
function joinQingyunSect(){const p=state.player;if(p.sect==='青云宗')return;p.sect='青云宗';p.sectRank='外门弟子';p.sectContribution=Math.max(0,p.sectContribution||0);p.sectTasksCompleted=p.sectTasksCompleted||0;p.sectTask=null;ensureSectCareerShape();addWorld(`${p.name}通过青云宗收徒试炼，正式列入外门名册。`,'major')}
function sectMonthKey(){return (state.time.year-1)*12+state.time.month}
function sectTaskAvailable(d){return !!d&&sectRankIndex()>=d.minRank}
function acceptSectTask(id){
 if(!isSectMember())return showResult('尚未入宗','你现在还不是青云宗弟子。','bad');
 if(state.player.location!=='青云山')return showResult('不在山门','领取宗门任务需要先回到青云山。','bad');
 if(state.player.sectTask)return showResult('已有任务',`先完成【${state.player.sectTask.title}】。`,'bad');
 const d=SECT_TASKS[id];if(!d||!sectTaskAvailable(d))return showResult('身份不足','你的宗门身份还不足以接取这项差事。','bad');
 state.player.sectTask={id:d.id,title:d.title,progress:0,need:d.need||1,acceptedDay:dayNumber()};addPersonal(`你接下宗门任务【${d.title}】：${d.desc}`,'major');save();render();showResult('宗门任务已接',`【${d.title}】\n${d.desc}`,'good')
}
function finishSectTask(d){const p=state.player;p.sectContribution+=d.contrib;p.spiritStones+=d.stones||0;p.reputation+=d.rep||0;p.rareMaterials=(p.rareMaterials||0)+(d.rare||0);p.insight=(p.insight||0)+(d.insight||0);p.sectTasksCompleted++;if(d.senior)p.sectSeniorTasksCompleted=(p.sectSeniorTasksCompleted||0)+1;p.sectTask=null;addPersonal(`你完成【${d.title}】，宗门贡献 +${d.contrib}${d.stones?'，灵石 +'+d.stones:''}${d.rare?'，高阶灵材 +'+d.rare:''}${d.insight?'，悟道点 +'+d.insight:''}。`,'major');if(d.senior)addFactionStanding('qingyun',2,'完成高阶宗门差事')}
function completeRoutineSectTask(){const t=state.player.sectTask;if(!t)return;const d=SECT_TASKS[t.id];if(!d||d.combat)return;if(livingActionGuard())return;advanceDays(d.days);if(state.flags.dead)return;finishSectTask(d);save();render();showResult('任务完成',`【${d.title}】\n宗门贡献 +${d.contrib}${d.stones?'\n灵石 +'+d.stones:''}`,'good')}
function onSectCombatWin(e){const t=state.player.sectTask;if(!t)return;const d=SECT_TASKS[t.id];if(!d||!d.combat)return;if(!d.locations.includes(state.player.location))return;if(d.kinds&&d.kinds.length&&!d.kinds.includes(e.kind))return;t.progress++;addPersonal(`【宗门任务】${d.title}进度 ${t.progress}/${t.need}。`,'good');if(t.progress>=t.need)finishSectTask(d)}
function sectStipend(){const i=sectRankIndex();return [{stones:3,herbs:1,rare:0,insight:0},{stones:6,herbs:2,rare:0,insight:0},{stones:12,herbs:3,rare:1,insight:0},{stones:20,herbs:4,rare:1,insight:0},{stones:35,herbs:6,rare:2,insight:1}][i]}
function claimSectStipend(){
 if(!isSectMember())return showResult('尚未入宗','你没有宗门月俸。','bad');if(state.player.location!=='青云山')return showResult('不在山门','月俸要到青云山宗务堂领取。','bad');
 const key=sectMonthKey();if(state.player.sectLastStipend===key)return showResult('本月已领','这个月的宗门月俸已经领取。');
 const p=state.player,d=sectStipend(),swordRecognition=p.daoPath==='sword'?2+Math.min(3,Math.floor(daoRenownValue('sword')/5)):0;p.sectLastStipend=key;p.spiritStones+=d.stones;p.herbs+=d.herbs;p.rareMaterials=(p.rareMaterials||0)+d.rare;p.insight=(p.insight||0)+d.insight;if(swordRecognition)p.sectContribution+=swordRecognition;addPersonal(`你领取${p.sectRank}月俸：灵石 ${d.stones}、灵草 ${d.herbs}${d.rare?'、高阶灵材 '+d.rare:''}${d.insight?'、悟道点 '+d.insight:''}${swordRecognition?'。剑脉认可你的道途名望，宗门贡献 +'+swordRecognition:'。'}`,'good');save();render();showResult('领取月俸',`灵石 +${d.stones}\n灵草 +${d.herbs}${d.rare?'\n高阶灵材 +'+d.rare:''}${d.insight?'\n悟道点 +'+d.insight:''}`,'good')
}
function sectExchange(kind){const p=state.player;if(!isSectMember())return;
 if(kind==='stones'){if(p.sectContribution<10)return showResult('贡献不足','兑换需要 10 点宗门贡献。','bad');p.sectContribution-=10;p.spiritStones+=4;showResult('贡献兑换','宗门贡献 -10\n灵石 +4','good')}
 else if(kind==='herbs'){if(p.sectContribution<8)return showResult('贡献不足','兑换需要 8 点宗门贡献。','bad');p.sectContribution-=8;p.herbs+=3;showResult('贡献兑换','宗门贡献 -8\n灵草 +3','good')}
 else if(kind==='manual'){if(p.manual==='赤炎诀')return showResult('已经掌握','你当前已经在修炼《赤炎诀》。');if(p.sectContribution<30)return showResult('贡献不足','兑换《赤炎诀》需要 30 点宗门贡献。','bad');p.sectContribution-=30;p.manual='赤炎诀';p.manualProf=0;addPersonal('你用宗门贡献换得《赤炎诀》，并改修此功。','major');showResult('兑换功法','获得并改修《赤炎诀》\n宗门贡献 -30','good')}
 else if(kind==='rare'){if(sectRankIndex()<2)return showResult('身份不足','真传弟子才能动用宗门高阶灵材配额。','bad');if(p.sectContribution<36)return showResult('贡献不足','兑换 1 份高阶灵材需要 36 点宗门贡献。','bad');p.sectContribution-=36;p.rareMaterials=(p.rareMaterials||0)+1;showResult('高阶配额','宗门贡献 -36\n高阶灵材 +1','good')}
 else if(kind==='insight'){if(sectRankIndex()<3)return showResult('身份不足','执事以上才能申请宗门悟道名额。','bad');if(p.sectContribution<60)return showResult('贡献不足','申请一次悟道名额需要 60 点宗门贡献。','bad');p.sectContribution-=60;p.insight=(p.insight||0)+1;showResult('悟道名额','宗门贡献 -60\n悟道点 +1','good')}
 save();render()
}
function mentorLessonCooldown(){const last=state.player.sectLastMentorDay||0;if(!last)return 0;return Math.max(0,30-(dayNumber()-last))}
function chooseSectMentor(id){const p=state.player,m=SECT_MENTORS[id];if(!isSectMember()||sectRankIndex()<1)return showResult('尚无拜师资格','晋升内门后才可正式择师。','bad');if(p.location!=='青云山')return showResult('不在山门','拜师需要回到青云山。','bad');if(!m)return;if(p.sectMentor)return showResult('已有师承','你已经拜入 '+SECT_MENTORS[p.sectMentor].name+' 门下。本版不允许随意改换师门。','bad');p.sectMentor=id;p.sectMentorBond=0;p.sectLastMentorDay=0;addPersonal(`你正式拜${m.title}【${m.name}】为师。`,'major');save();render();showResult('拜师完成',`${m.title} · ${m.name}\n${m.desc}`,'good')}
function seekMentorGuidance(){const p=state.player;if(!p.sectMentor)return showResult('尚无师承','先选择一位师父。','bad');if(p.location!=='青云山')return showResult('不在山门','请教师父需要回到青云山。','bad');const cd=mentorLessonCooldown();if(cd>0)return showResult('请教冷却','师父最近已经指点过你，还需 '+cd+' 日。','bad');if(p.sectContribution<8)return showResult('贡献不足','每次正式请教需从自己的宗门配额中扣除 8 点贡献。','bad');if(livingActionGuard())return;const m=SECT_MENTORS[p.sectMentor];p.sectContribution-=8;p.sectMentorBond=(p.sectMentorBond||0)+1;p.sectLastMentorDay=dayNumber();p.manualProf+=30;let pathGain=0,insightGain=0,rareGain=0;if(m.path===p.daoPath&&p.daoPath!=='none'){pathGain=15;p.daoMastery=(p.daoMastery||0)+pathGain}if(p.sectMentorBond===3||p.sectMentorBond===6)insightGain=1;if(p.sectMentorBond===6)rareGain=1;p.insight=(p.insight||0)+insightGain;p.rareMaterials=(p.rareMaterials||0)+rareGain;advanceDays(1);if(state.flags.dead)return;addPersonal(`【师承】${m.name}指点你一日，师徒情分提升至 ${p.sectMentorBond}，功法熟练度 +30${pathGain?'，同道修行使道途熟练 +'+pathGain:''}${insightGain?'，悟道点 +'+insightGain:''}${rareGain?'，获赠高阶灵材 +'+rareGain:''}。`,'good');save();render();showResult('师父指点',`师徒情分 ${p.sectMentorBond}\n功法熟练度 +30${pathGain?'\n道途熟练 +'+pathGain:''}${insightGain?'\n悟道点 +'+insightGain:''}${rareGain?'\n高阶灵材 +'+rareGain:''}`,'good')}
function sectAssessmentCooldown(){const last=state.player.sectLastAssessmentDay||0;if(!last)return 0;return Math.max(0,30-(dayNumber()-last))}
function takeSectAssessment(){const p=state.player;if(!isSectMember())return showResult('尚未入宗','你不是青云宗弟子。','bad');if(p.location!=='青云山')return showResult('不在山门','晋升考核只能在青云山进行。','bad');if(livingActionGuard())return;const current=sectRankIndex(),target=current+1;if(target>=SECT_RANKS.length)return showResult('已居长老','你已经进入青云宗长老席。');if((p.sectAssessmentLevel||0)>=target)return showResult('考核已过','本级晋升考核已经通过，满足其余条件后即可晋升。');const d=SECT_ASSESSMENTS[target],cd=sectAssessmentCooldown();if(cd>0)return showResult('考核冷却','上次考核后需休整 '+cd+' 日。','bad');if(p.realmIndex<d.realm)return showResult('境界不足',`本次考核至少需要 ${REALMS[d.realm].name}。`,'bad');const enemy={name:d.name,kind:'宗门考核',realm:d.realm,hp:d.hp,atk:d.atk,reward:{stones:[0,0],herbs:[0,0],rep:0},weight:0,nonLethal:true,sectAssessment:true,assessmentLevel:target};addPersonal(`你进入【${d.title}】，宗门以${d.name}检验你的真实战力。`,'major');startCombat(enemy)}
function onSectAssessmentResult(win,e){if(!e||!e.sectAssessment)return;const p=state.player,level=e.assessmentLevel||0,d=SECT_ASSESSMENTS[level];p.sectLastAssessmentDay=dayNumber();if(win){p.sectAssessmentLevel=Math.max(p.sectAssessmentLevel||0,level);p.sectContribution+=d.bonus;addPersonal(`【宗门考核通过】${d.title}，宗门贡献 +${d.bonus}。`,'major')}else addPersonal(`【宗门考核落败】${d.title}未能通过，30日后方可再试。`,'bad')}
function sectPromotionMissing(target){const p=state.player,d=SECT_PROMOTIONS[target],miss=[];if(p.realmIndex<d.realm)miss.push('境界需达到 '+REALMS[d.realm].name);if(p.sectContribution<d.contribution)miss.push('宗门贡献需 '+d.contribution);if((p.sectTasksCompleted||0)<d.tasks)miss.push('累计任务需 '+d.tasks);if((p.sectSeniorTasksCompleted||0)<d.senior)miss.push('高阶差事需 '+d.senior);if((p.sectMentorBond||0)<d.bond)miss.push('师徒情分需 '+d.bond);if(factionStandingValue('qingyun')<d.standing)miss.push('青云宗关系需 '+d.standing);if((p.sectAssessmentLevel||0)<d.assessment)miss.push('需通过本级宗门考核');return miss}
function promoteSect(){const p=state.player;if(!isSectMember())return;const current=sectRankIndex(),target=current+1;if(target>=SECT_RANKS.length)return showResult('已居长老','你已经是青云宗长老。');const d=SECT_PROMOTIONS[target],miss=sectPromotionMissing(target);if(miss.length)return showResult('晋升条件不足',miss.join('\n'),'bad');p.sectContribution-=d.cost;p.sectRank=d.rank;p.reputation+=d.rep;addFactionStanding('qingyun',target>=2?5:3,'宗门晋升');addPersonal(`你通过全部考核，正式晋升为青云宗【${d.rank}】。`,'major');addWorld(`${p.name}晋升青云宗${d.rank}。`,'major');save();render();showResult('宗门晋升',`新身份：${d.rank}\n宗门贡献 -${d.cost}\n声望 +${d.rep}`,'good')}
function renderSect(){
 const info=$('sectInfo'),actions=$('sectActions');if(!info||!actions)return;const p=state.player;
 if(!isSectMember()){info.innerHTML='<div class="section-tip">你目前无门无派。青云宗开山收徒时，通过考核才会获得正式弟子身份。</div>';actions.innerHTML='';return}
 ensureSectCareerShape();const rank=sectRankIndex(),t=p.sectTask,m=p.sectMentor?SECT_MENTORS[p.sectMentor]:null,next=rank<SECT_RANKS.length-1?SECT_PROMOTIONS[rank+1]:null;const taskText=t?`<div class="skill-card"><div class="skill-head"><b>当前任务：${esc(t.title)}</b><span>${SECT_TASKS[t.id]?.combat?`进度 ${t.progress}/${t.need}`:'进行中'}</span></div><div class="skill-desc">${SECT_TASKS[t.id]?.desc||''}</div></div>`:'';const mentorText=m?`${m.title} · ${m.name} · 情分 ${p.sectMentorBond}`:'尚未拜师';const assessText=rank>=SECT_RANKS.length-1?'长老席位已定':((p.sectAssessmentLevel||0)>=rank+1?'本级考核已通过':'本级考核未通过');
 info.innerHTML=`<div class="kv"><span>宗门</span><b>青云宗</b></div><div class="kv"><span>身份</span><b>${p.sectRank}</b></div><div class="kv"><span>宗门贡献</span><b>${p.sectContribution}</b></div><div class="kv"><span>已完成任务</span><b>${p.sectTasksCompleted}</b></div><div class="kv"><span>高阶差事</span><b>${p.sectSeniorTasksCompleted||0}</b></div><div class="kv"><span>师承</span><b>${esc(mentorText)}</b></div><div class="kv"><span>晋升考核</span><b>${esc(assessText)}</b></div>${taskText}`;
 if(t){const d=SECT_TASKS[t.id];actions.innerHTML=d.combat?`<div class="section-tip">前往【${d.locations.join(' / ')}】完成真实战斗即可自动累计任务进度。</div>`:`<button class="primary" data-sect-complete>执行任务 · ${d.days}日</button>`}else actions.innerHTML='<div class="event-actions">'+Object.values(SECT_TASKS).filter(sectTaskAvailable).map(d=>`<button data-sect-task="${d.id}">${d.title} · 贡献${d.contrib}</button>`).join('')+'</div>';
 actions.innerHTML+=`<div class="event-actions"><button data-sect-stipend>领取本月月俸</button><button data-sect-exchange="stones">10贡献 → 4灵石</button><button data-sect-exchange="herbs">8贡献 → 3灵草</button><button data-sect-exchange="manual">30贡献 → 《赤炎诀》</button>${rank>=2?'<button data-sect-exchange="rare">36贡献 → 高阶灵材</button>':''}${rank>=3?'<button data-sect-exchange="insight">60贡献 → 悟道名额</button>':''}</div>`;
 if(rank>=1){if(!m)actions.innerHTML+='<div class="section-tip">内门以后可择一位师父。师承一旦确定，本版不能随意改换。</div><div class="event-actions">'+Object.values(SECT_MENTORS).map(x=>`<button data-sect-mentor="${x.id}">${x.title} · ${x.name}</button>`).join('')+'</div>';else actions.innerHTML+=`<div class="event-actions"><button data-mentor-guidance ${mentorLessonCooldown()>0?'disabled':''}>请教师父 · 8贡献${mentorLessonCooldown()>0?' · '+mentorLessonCooldown()+'日后':''}</button></div>`}
 if(next){const miss=sectPromotionMissing(rank+1);actions.innerHTML+=`<div class="skill-card"><div class="skill-head"><b>下一身份：${next.rank}</b><span>${miss.length?'尚缺条件':'条件已齐'}</span></div><div class="skill-desc">境界 ${REALMS[next.realm].name} · 贡献 ${next.contribution} · 总任务 ${next.tasks}${next.senior?' · 高阶差事 '+next.senior:''}${next.bond?' · 师徒情分 '+next.bond:''}${next.standing?' · 青云关系 '+next.standing:''} · 晋升消耗 ${next.cost}贡献</div></div><div class="event-actions"><button data-sect-assessment ${(p.sectAssessmentLevel||0)>=rank+1?'disabled':''}>${(p.sectAssessmentLevel||0)>=rank+1?'本级考核已通过':'参加晋升考核'}</button><button class="primary" data-sect-promote ${miss.length?'disabled':''}>晋升${next.rank}</button></div>`}
 actions.querySelectorAll('[data-sect-task]').forEach(b=>b.onclick=()=>acceptSectTask(b.dataset.sectTask));const c=actions.querySelector('[data-sect-complete]');if(c)c.onclick=completeRoutineSectTask;const st=actions.querySelector('[data-sect-stipend]');if(st)st.onclick=claimSectStipend;actions.querySelectorAll('[data-sect-exchange]').forEach(b=>b.onclick=()=>sectExchange(b.dataset.sectExchange));actions.querySelectorAll('[data-sect-mentor]').forEach(b=>b.onclick=()=>chooseSectMentor(b.dataset.sectMentor));const mg=actions.querySelector('[data-mentor-guidance]');if(mg)mg.onclick=seekMentorGuidance;const ass=actions.querySelector('[data-sect-assessment]');if(ass)ass.onclick=takeSectAssessment;const pr=actions.querySelector('[data-sect-promote]');if(pr)pr.onclick=promoteSect;renderSectLifePanel(info,actions)
}

